def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Final round: opponent's action is already determined, so defect is strictly best.
    if n >= 99:
        return 'D'

    # Basic counts.
    my_d = 0
    opp_d = 0
    for me, op in history:
        if me == 'D':
            my_d += 1
        if op == 'D':
            opp_d += 1
    opp_c = n - opp_d

    last_me, last_op = history[-1]

    # Trailing streaks.
    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    # Recent five opponent actions.
    recent5 = history[-5:] if n >= 5 else history
    recent5_opp_c = 0
    for pair in recent5:
        if pair[1] == 'C':
            recent5_opp_c += 1

    # Transition statistics: opponent current action vs our previous action.
    w = min(n, 15)
    start_i = max(1, n - w)

    after_c_total = 0
    after_c_d = 0
    after_d_total = 0
    after_d_d = 0
    copy_total = 0
    copy_match = 0

    for i in range(start_i, n):
        prev_me = history[i - 1][0]
        opp_now = history[i][1]

        copy_total += 1
        if opp_now == prev_me:
            copy_match += 1

        if prev_me == 'C':
            after_c_total += 1
            if opp_now == 'D':
                after_c_d += 1
        else:
            after_d_total += 1
            if opp_now == 'D':
                after_d_d += 1

    opp_c_rate = opp_c / float(n)

    if after_c_total:
        cd_rate = after_c_d / float(after_c_total)
    else:
        cd_rate = 0.0

    if after_d_total:
        retaliation_rate = after_d_d / float(after_d_total)
    else:
        retaliation_rate = 1.0

    if copy_total:
        copy_rate = copy_match / float(copy_total)
    else:
        copy_rate = 0.0

    # Sustained, unresponsive hostility: mostly ALLD-like behavior.
    hostile = (
        (opp_d_streak >= 5 and recent5_opp_c == 0) or
        (opp_d_streak >= 2 and opp_c_rate < 0.30) or
        (opp_d_streak >= 4 and cd_rate >= 0.70 and opp_c_rate < 0.55)
    )
    if hostile:
        return 'D'

    # Detect the measured periodic_D pattern: D,D,C,C,C repeated, with next likely D.
    if n >= 5:
        last5_op = tuple(history[i][1] for i in range(n - 5, n))
        if (last5_op == ('D', 'D', 'C', 'C', 'C') and
                opp_d_streak == 0 and
                recent5_opp_c >= 3 and
                opp_c_rate > 0.45 and
                copy_rate < 0.9):
            return 'D'

    if last_op == 'C':
        # Opponent has cooperated every observed round for a while: exploit if forgiving/ALLC-like.
        if opp_c == n and n >= 20:
            return 'D'

        # If our defections were not retaliated against and opponent is cooperative, keep exploiting.
        if after_d_total >= 2 and retaliation_rate <= 0.25 and opp_c_rate >= 0.65:
            return 'D'

        # Occasional rare probe against a cooperative non-retaliator.
        if (n >= 12 and
                recent5_opp_c >= 4 and
                opp_d_streak == 0 and
                my_d_streak == 0 and
                rng.random() < 0.02):
            return 'D'

        return 'C'

    # last_op == 'D'
    # Break punishment cycles after enough mutual defection.
    if my_d_streak >= 2:
        return 'C'

    # One defection of ours was enough; forgive next round unless clearly hostile.
    if my_d_streak == 1:
        if cd_rate >= 0.75 and opp_c_rate < 0.45:
            return 'D'
        return 'C'

    # Short opponent defect streaks are treated as anomalies against cooperative play.
    if opp_d_streak <= 2:
        return 'C'

    # Moderate-to-high unprovoked exploitation: punish, but only when opponent is not mostly cooperative.
    if opp_d_streak >= 3 and cd_rate >= 0.45 and opp_c_rate < 0.65:
        return 'D'

    # Mostly defecting opponent with no recent cooperation.
    if opp_c_rate < 0.35:
        return 'D'

    # Default to cooperative reset for TFT/generous opponents after short bursts.
    return 'C'
